CREATE OR REPLACE FUNCTION public.manage_stock_category(old_name text, new_name text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE clean text:=nullif(trim(new_name),''); previous text:=nullif(old_name,''); BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Admin only'; END IF; LOCK TABLE public.stock_categories IN SHARE ROW EXCLUSIVE MODE; IF previous IS NULL THEN IF clean IS NULL THEN RAISE EXCEPTION 'Enter a category name'; END IF; INSERT INTO public.stock_categories VALUES(clean); ELSE PERFORM 1 FROM public.stock_categories WHERE name=previous FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Category not found'; END IF; IF clean IS NULL THEN IF EXISTS(SELECT 1 FROM public.items WHERE category=previous) THEN RAISE EXCEPTION 'This category is used by stock and cannot be removed'; END IF; DELETE FROM public.stock_categories WHERE name=previous; ELSE UPDATE public.stock_categories SET name=clean WHERE name=previous; UPDATE public.items SET category=clean WHERE category=previous AND status='In Stock'; END IF; END IF; END $$;